    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00631",
        "explanation": "The doctor adapted to patient anxiety by producing a usable question list for the visit.",
        "quote": "问题清单"
      },
      {
        "event_id": "lite_evt_00701",
        "explanation": "The doctor assigned a practical family role for result tracking.",
        "quote": "家属负责查小程序"
      }
    ]
  },
