      "citations": [
        {
          "event_id": "lite_evt_00148",
          "explanation": "The doctor separated the breast target requiring pathology from lower-priority thyroid/lung issues.",
          "quote": "定位结节切除"
        },
        {
          "event_id": "lite_evt_00312",
          "explanation": "The doctor reinforced that thyroid and lung nodules should not overtake the breast pathology pathway.",
          "quote": "甲状腺和肺部的小结节目前都不紧急"
        }
      ],
